<?php require dirname(__DIR__).'/includes/app.php';$admins=admins();if($admins){header('Location:'.site_url('/admin/'));exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$user=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');if(strlen($user)<3||strlen($pass)<12){$error='Use a username of at least 3 characters and a password of at least 12 characters.';}elseif(!db()){$error='Database connection failed. Configure config/database.php and import database/schema.sql first.';}elseif(admin_create($user,$pass)){header('Location:'.site_url('/admin/'));exit;}else{$error='Unable to create the administrator. The username may already exist.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Setup</title><link rel="stylesheet" href="<?=e(asset_url('/admin/admin.css'))?>"></head><body class="login-body"><form class="login-card" method="post"><div class="admin-logo">GB</div><h1>Create Admin</h1><p>First-time SQL-backed setup for Galindos Builders LLC.</p><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Username<input name="username" required autocomplete="username"></label><label>Password<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><button>Create Administrator</button></form></body></html>